import{_ as a,o,c as s,a6 as i}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"Entenda rankings e competições","description":"","frontmatter":{"title":"Entenda rankings e competições","docId":"user.points.rankings","translationKey":"user.points.rankings","locale":"pt","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"dcf08e4ef08a28fc3e32216b2017b5f208afc57a91e537fd3b90a6f0ed1f041e","translationRevision":"ffee3cf8b07660848410ca5f46613ff8ffd5781d5078321dc4dc55a8622f401d","order":30},"headers":[],"relativePath":"pt/user/points/rankings.md","filePath":"pt/user/points/rankings.md","lastUpdated":1794611623000}'),n={name:"pt/user/points/rankings.md"};function t(r,e,d,c,p,l){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="understand-rankings-and-competitions" tabindex="-1">Entenda rankings e competições <a class="header-anchor" href="#understand-rankings-and-competitions" aria-label="Permalink to &quot;Entenda rankings e competições {#understand-rankings-and-competitions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Escolha a visualização classificada adequada e reconheça os limites da área de rankings em desenvolvimento. Você precisa de atividade recebida para ter pontuações significativas. Comece pela classificação comum de <a href="./rules.html">Points</a> ou pelos painéis dos principais espectadores no <a href="./../live/feed.html">Live feed</a> quando precisar apenas inspecionar os espectadores atuais.</p><h2 id="use-the-right-view" tabindex="-1">Use a visualização correta <a class="header-anchor" href="#use-the-right-view" aria-label="Permalink to &quot;Use a visualização correta {#use-the-right-view}&quot;">​</a></h2><ol><li>Em <strong>Points</strong>, pesquise um espectador e ordene por pontos, nível ou identidade do espectador. Atualize antes de comparar um ajuste manual com uma atribuição.</li><li>Em <strong>Live feed</strong>, inspecione os painéis disponíveis de espectadores classificados. Eles podem receber instantâneos do mecanismo de ranking independentemente da tabela de saldos de pontos.</li><li>Para um overlay, abra <a href="./../overlays/">Overlays</a>, selecione o tipo ranking e inspecione as opções de fonte. Uma fonte de ranking configurada precisa existir antes de sua saída aparecer.</li></ol><p>A área dedicada <strong>Rankings &amp; competitions</strong> é experimental. Sua rota de frontend é <code>#/rankings</code>, mas ela está deliberadamente oculta na navegação principal e não é restaurada como aba inicial. A ausência de um item na barra lateral não significa que a rota ou o mecanismo de ranking tenha sido removido.</p><h2 id="configure-an-experimental-ranking" tabindex="-1">Configure um ranking experimental <a class="header-anchor" href="#configure-an-experimental-ranking" aria-label="Permalink to &quot;Configure um ranking experimental {#configure-an-experimental-ranking}&quot;">​</a></h2><p>Se seu ambiente expuser essa área, comece com um criador, uma sala, agrupamento por usuário e uma janela de sessão. Adicione uma métrica anunciada, como <code>tiktok.like</code> / <code>like.count</code>, com peso <code>1</code>. Defina um limite modesto de resultados e crie a definição. O formulário também aceita janelas móveis e diárias, com limites explícitos de duração/eventos ou deslocamento de fuso horário.</p><p>Leia o instantâneo resultante antes de introduzir fontes adicionais. Pausar e retomar afetam a coleta do ranking; redefinir limpa intencionalmente o estado do ranking. Opções de competição e fontes relacionadas a votos têm suas próprias regras de agrupamento. Não presuma que redefinir pontos também redefina uma competição nem que todo agrupamento personalizado funcione com toda métrica.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>As classificações comuns estão disponíveis; a página dedicada de gerenciamento permanece experimental. As pontuações vêm do host, não da contagem de linhas exibidas no feed. A aceitação em transmissão real/OBS e todas as combinações de competição não são comprovadas por este guia.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Confira criador, sala, ativação de fontes, janela e estado de pausa quando as pontuações continuarem vazias. Remova combinações de fonte/grupo incompatíveis em vez de inventar nomes de campos. Preserve dados importantes por meio de <a href="./../preferences/backups.html">backups</a> antes das redefinições e inclua o ID da definição e o código de diagnóstico em um relatório.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>A tabela Points solicita 100 espectadores e filtra/ordena apenas essas linhas. Atualizar ou ordenar por nome não pesquisa toda a base. Os rankings do feed mostram 10 linhas por sessão de criador/sala: diamantes de presentes em Top e quantidades em Likes, acompanhando até 5.000 espectadores. Não medem pontos salvos. Confira unidades e limites da sessão antes de comparar totais.</p>',15)])])}const f=a(n,[["render",t]]);export{u as __pageData,f as default};
